CREATE TABLE task_lifecycle_command_receipts(receipt_id TEXT PRIMARY KEY,team_id TEXT NOT NULL,command_name TEXT NOT NULL CHECK(command_name IN('transition-task-in-progress','submit-root-delivery','accept-root-delivery','reject-root-delivery','transition-subtask-in-review','accept-subtask','reject-subtask','cancel-task','close-task','start-execution')),command_schema_version INTEGER NOT NULL CHECK(command_schema_version>=1),idempotency_key TEXT NOT NULL,command_hash TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('applied','no_op')),committed_revisions_json TEXT NOT NULL,event_refs_json TEXT NOT NULL,result_available INTEGER NOT NULL CHECK(result_available IN(0,1)),result_json TEXT,commit_time INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX task_lifecycle_command_receipts_idempotency_key_idx ON task_lifecycle_command_receipts(idempotency_key);
CREATE TABLE task_lifecycle_idempotency_tombstones(id TEXT PRIMARY KEY,team_id TEXT NOT NULL,command_name TEXT NOT NULL CHECK(command_name IN('transition-task-in-progress','submit-root-delivery','accept-root-delivery','reject-root-delivery','transition-subtask-in-review','accept-subtask','reject-subtask','cancel-task','close-task','start-execution')),idempotency_key TEXT NOT NULL,command_hash TEXT NOT NULL,receipt_id TEXT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('applied','no_op')),result_available INTEGER NOT NULL CHECK(result_available IN(0,1)),created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX task_lifecycle_tombstones_idempotency_key_idx ON task_lifecycle_idempotency_tombstones(idempotency_key);
CREATE INDEX task_lifecycle_tombstones_receipt_idx ON task_lifecycle_idempotency_tombstones(receipt_id);
